function friendlyGuidance(c) { const prefix = { A5:'Set the policy, accountability, and governance foundation.', A6:'Make sure people understand and follow their security responsibilities.', A7:'Protect the physical places and equipment that handle information.', A8:'Apply technical safeguards consistently across systems and services.' }[c.theme]; const evidence = { A5:'Policies, approvals, registers, committee minutes, supplier records, and review logs.', A6:'Training records, role descriptions, joiner/leaver checklists, and signed acknowledgements.', A7:'Access logs, visitor records, CCTV review records, facility inspections, and maintenance logs.', A8:'Configuration exports, scan reports, tickets, architecture diagrams, system logs, and test results.' }[c.theme]; return { intent:prefix, evidence }; }
function saveLegacy() { localStorage.setItem('asteria-evidence', JSON.stringify(state.evidence)); localStorage.setItem('asteria-evidence-details', JSON.stringify(state.evidenceDetails)); localStorage.setItem('asteria-documents', JSON.stringify(state.documents)); localStorage.setItem('asteria-gaps', JSON.stringify(state.gaps)); localStorage.setItem('asteria-audits', JSON.stringify(state.audits)); localStorage.setItem('asteria-statuses', JSON.stringify(state.statuses)); localStorage.setItem('asteria-soa', JSON.stringify(state.soa)); }
async function loadCRFControls() { if(state.crfControls.length || typeof XLSX === 'undefined') return; try { const response=await fetch('fictional-crf-catalogue.json'); const workbook=XLSX.read(await response.arrayBuffer(),{type:'array'}); const rows=XLSX.utils.sheet_to_json(workbook.Sheets['CRF CST 2026'],{header:1,defval:''}); state.crfControls=rows.slice(6).filter(row=>row[1] && row[3]).map(row=>({ id:String(row[1]), family:String(row[2]), description:String(row[3]), evidence:String(row[6] || ''), findings:String(row[7] || ''), gap:String(row[8] || ''), risk:String(row[9] || ''), action:String(row[10] || ''), status:String(row[11] || 'Not assessed') })); localStorage.setItem('asteria-crf-controls',JSON.stringify(state.crfControls)); if(state.page==='controls' || state.assignmentSet==='crf') render(); } catch(error) { console.warn('CRF workbook could not be loaded',error); } }
