function layout(content,title) { return `<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#"><span class="brand-mark"></span><span class="brand-name">asteria</span></a><div class="eyebrow">Information security</div><nav class="nav"><div class="nav-section-label">Command center</div>${nav('dashboard','◒','Overview')}${nav('roadmap','＋','Product direction')}<div class="nav-section-label">ISMS</div>${nav('controls','⊙','Control catalogue')}${nav('soa','▤','Statement of Applicability')}${nav('policies','▤','Policies')}${nav('procedures','≡','Procedures')}${nav('evidence','□','Evidence library')}<div class="nav-section-label">Assurance</div>${nav('audits','◌','Internal audits')}${nav('gaps','△','Gap assessment')}${nav('actions','↗','Action plan')}</nav><div class="sidebar-footer"><div class="org-chip"><span class="avatar">NF</span><div><strong>Atlas Demo Co.</strong><small>Fictional Region · Demo workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div><button class="mobile-menu" onclick="toggleMenu()">☰</button><span class="crumb">Workspace / <strong>${title}</strong></span></div><div class="top-actions"><button class="icon-btn" title="Notifications" onclick="toast('Notifications are clear')">♧</button><div class="user-pill"><span class="avatar">MA</span><span>Security Office</span><button class="logout" onclick="logout()">Sign out</button></div></div></header><section class="content">${content}</section></main></div>`; }
function openControl(ref) { const c=controls.find(x=>x.ref===ref); if(!c) return; const guidance=friendlyGuidance(c); state.selectedControl=ref; const existing=state.soa[ref]?.justification || ''; document.body.insertAdjacentHTML('beforeend',`<div class="drawer-backdrop" id="modal" onclick="if(event.target===this)closeModal()"><aside class="control-drawer"><div class="drawer-head"><div><div class="eyebrow">${c.ref} / ${themes[c.theme]} theme</div><h2>${c.title}</h2><div style="margin-top:9px">${badge(state.statuses[ref])}</div></div><button class="drawer-close" aria-label="Close control details" onclick="closeModal()">×</button></div><div class="drawer-body"><section class="drawer-section"><div class="drawer-explainer"><label>Control intent</label><p>${c.description}</p></div></section><section class="drawer-section"><div class="drawer-meta-grid"><div class="drawer-meta"><span>Linked evidence</span><strong>${evidenceFor(ref).length} item${evidenceFor(ref).length===1?'':'s'}</strong></div><div class="drawer-meta"><span>SoA decision</span><strong>${state.soa[ref]?.applicable?'In scope':'Not applicable'}</strong></div></div></section><section class="drawer-section"><div class="drawer-section-title"><h3>Implementation</h3></div><div class="field"><label>Status</label><select id="modal-status"><option value="implemented" ${state.statuses[ref]==='implemented'?'selected':''}>Implemented</option><option value="partial" ${state.statuses[ref]==='partial'?'selected':''}>Partial</option><option value="open" ${state.statuses[ref]==='open'?'selected':''}>Not started</option><option value="na" ${state.statuses[ref]==='na'?'selected':''}>Not applicable</option></select></div><div class="field"><label>SoA rationale / implementation note</label><textarea id="modal-note" placeholder="Explain how this control is implemented or why it is excluded.">${existing}</textarea></div></section><section class="drawer-section"><div class="drawer-section-title"><h3>Evidence</h3><span class="control-sub">${friendlyGuidance(c).evidence}</span></div><div class="field"><select id="modal-evidence" class="select evidence-modal-select" multiple size="4" onchange="renderEvidenceDetails('${ref}')">${evidenceOptions(ref)}</select><div class="field-help">Select one or more items. Page ranges and match notes appear below.</div></div><div id="evidence-detail-fields"></div></section><section class="drawer-section"><div class="drawer-section-title"><h3>Policies and procedures</h3></div>${documentPicker(ref)}</section><div class="drawer-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveControl('${ref}')">Save control</button></div></div></aside></div>`); requestAnimationFrame(()=>renderEvidenceDetails(ref)); }
function selectAuditTest(id) { state.activeAuditTest=id; render(); }
function auditsPage() { const audit=state.audits[0]; const tests=state.auditTests.filter(t=>t.auditId===audit.id); const active=tests.find(t=>t.id===state.activeAuditTest) || tests[0]; const c=controls.find(item=>item.ref===active?.controlRef); const progress=auditProgress(audit); const list=tests.map(test=>{const item=controls.find(x=>x.ref===test.controlRef); return `<button class="audit-control ${test.id===active?.id?'active':''}" onclick="selectAuditTest('${test.id}')"><span><b>${test.controlRef}</b><br>${item?.title || test.controlRef}</span>${resultBadge(test.result)}</button>`;}).join(''); const currentFinding=active?.findingId ? state.findings.find(f=>f.id===active.findingId) : null; return layout(`<div class="page-head"><div><div class="eyebrow">Assurance / Internal audit workbench</div><h1>Test the system, not just the paperwork.</h1><p class="subhead">Move through the audit sample one control at a time. Keep the procedure, evidence, result, notes, and finding in one working view.</p></div><button class="button button-primary" onclick="openAuditCreate()">+ New audit</button></div><div class="audit-workbench" data-tour="audit-workspace"><aside class="audit-sidebar"><div class="card"><div class="panel-head"><div><h2>${audit.name}</h2><p>${tests.length} control tests</p></div><span class="badge amber">${progress}%</span></div><div class="audit-control-list">${list || '<div class="empty-state">Create an audit test program first.</div>'}</div></div></aside><main class="audit-main"><div class="card">${active && c ? `<div class="audit-test-header"><div><div class="eyebrow">${active.controlRef} / Control test</div><h2>${c.title}</h2></div>${resultBadge(active.result)}</div><div class="source-description"><label>Test procedure</label><p>${active.procedure}</p></div><label class="eyebrow">Result</label><div class="test-result-grid">${['Pass','Partial','Fail','Not tested'].map(result=>`<button class="test-result ${active.result===result?'active':''}" onclick="document.getElementById('audit-result').value='${result}';document.querySelectorAll('.test-result').forEach(x=>x.classList.remove('active'));event.currentTarget.classList.add('active')">${result}</button>`).join('')}</div><select id="audit-result" hidden><option>Not tested</option><option>Pass</option><option>Partial</option><option>Fail</option></select><div class="field"><label>Evidence sampled</label><select id="audit-evidence" class="select evidence-modal-select" multiple size="4">${evidenceOptions(active.controlRef)}</select></div><div class="field"><label>Auditor notes</label><textarea id="audit-notes" placeholder="Record sample details, interviews, observations, and exceptions.">${active.notes || ''}</textarea></div><div class="field"><label>Finding if partial or failed</label><textarea id="audit-finding" placeholder="Describe the issue that should become corrective work.">${currentFinding?.description || ''}</textarea></div><div class="field"><label>Finding severity</label><select id="audit-severity"><option>Low</option><option selected>Medium</option><option>High</option></select></div><div class="drawer-actions"><button class="button button-primary" onclick="saveAuditTest('${active.id}')">Save result and continue</button></div>` : '<div class="empty-state">Select an audit test to begin.</div>'}</div></main><aside class="audit-context"><div class="card"><div class="panel-head"><div><h2>Control context</h2><p>Keep the audit decision grounded.</p></div></div>${c ? `<div class="context-block"><label>Control intent</label><p>${c.description}</p></div><div class="context-block"><label>Typical proof</label><p>${friendlyGuidance(c).evidence}</p></div><div class="context-block"><label>Linked evidence</label><p>${evidenceFor(c.ref).length} item${evidenceFor(c.ref).length===1?'':'s'} linked to this control.</p></div><div class="context-block"><label>Current SoA</label><p>${state.soa[c.ref]?.applicable?'In scope':'Not applicable'}</p></div>` : '<div class="empty-state">No control selected.</div>'}</div></aside></div>${auditFindingsPanel()}`, 'Internal audits'); }
function actionCard(g) { return `<article class="action-card" onclick="openGap('${g.id}')"><div style="display:flex;justify-content:space-between;gap:8px"><span class="control-ref">${g.id}</span>${riskBadge(g.risk)}</div><strong>${g.family}</strong><p>${g.action}</p><small>${g.owner} · ${g.due || 'No due date'}</small></article>`; }
function actionsPage() { const active=state.gaps.filter(g=>g.status!=='Closed'); const view=state.actionView || 'board'; const query=(state.actionQuery || '').toLowerCase(); const filtered=state.gaps.filter(g=>`${g.id} ${g.family} ${g.action} ${g.owner}`.toLowerCase().includes(query)); return layout(`<div class="page-head"><div><div class="eyebrow">Remediation / Corrective action plan</div><h1>Move open work to closure.</h1><p class="subhead">Gaps and audit findings become accountable actions with risk, owners, dates, and closure evidence.</p></div><div class="action-view-toggle"><button class="${view==='board'?'active':''}" onclick="state.actionView='board';render()">Board</button><button class="${view==='table'?'active':''}" onclick="state.actionView='table';render()">Table</button></div></div><div class="stats"><div class="card stat-card"><div class="eyebrow">Open actions</div><div class="stat-number">${active.length}</div><div class="stat-meta">Assessment remediation</div></div><div class="card stat-card"><div class="eyebrow">Audit findings</div><div class="stat-number">${(state.findings||[]).filter(f=>f.status!=='Closed').length}</div><div class="stat-meta">Need corrective work</div></div><div class="card stat-card"><div class="eyebrow">High risk</div><div class="stat-number">${active.filter(g=>g.risk==='High').length}</div><div class="stat-meta">Management attention</div></div></div><div class="card panel"><div class="table-toolbar"><div class="search"><input placeholder="Search actions by control, family, owner..." value="${state.actionQuery || ''}" oninput="state.actionQuery=this.value;render()" /></div><button class="link" onclick="exportActionsExcel()">Export to Excel</button></div>${view==='board' ? `<div class="action-board">${['Open','In progress','Closed','Awaiting evidence'].map(status=>`<section class="action-column"><h3>${status}<span>${filtered.filter(g=>g.status===status).length}</span></h3>${filtered.filter(g=>g.status===status).map(actionCard).join('') || '<div class="control-sub" style="padding:10px 4px">No actions here.</div>'}</section>`).join('')}</div>` : `<div style="overflow:auto"><table><thead><tr><th>Gap</th><th>Action</th><th>Owner</th><th>Due</th><th>Risk</th><th>Status</th><th></th></tr></thead><tbody>${filtered.map(g=>`<tr><td><span class="control-ref">${g.id}</span><div class="control-sub">${g.family}</div></td><td><div class="control-title">${g.action}</div><div class="control-sub">${g.gap}</div></td><td>${g.owner}</td><td>${g.due || 'Not set'}</td><td>${riskBadge(g.risk)}</td><td><select class="select action-status" onchange="updateGapStatus('${g.id}',this.value)"><option ${g.status==='Open'?'selected':''}>Open</option><option ${g.status==='In progress'?'selected':''}>In progress</option><option ${g.status==='Closed'?'selected':''}>Closed</option></select></td><td><button class="table-action" onclick="openGap('${g.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div>`}</div><div style="margin-top:17px">${auditFindingsPanel()}</div>`, 'Action plan'); }
ensureDemoData();
render();
