/* Local demo workflow layer. This deliberately stays browser-only for the partner demo. */
function save() { localStorage.setItem('asteria-evidence', JSON.stringify(state.evidence)); localStorage.setItem('asteria-evidence-details', JSON.stringify(state.evidenceDetails)); localStorage.setItem('asteria-documents', JSON.stringify(state.documents)); localStorage.setItem('asteria-gaps', JSON.stringify(state.gaps)); localStorage.setItem('asteria-audits', JSON.stringify(state.audits)); localStorage.setItem('asteria-findings', JSON.stringify(state.findings || [])); localStorage.setItem('asteria-audit-tests', JSON.stringify(state.auditTests || [])); localStorage.setItem('asteria-statuses', JSON.stringify(state.statuses)); localStorage.setItem('asteria-soa', JSON.stringify(state.soa)); localStorage.setItem('asteria-crf-soa', JSON.stringify(state.crfSoa || {})); }
function ensureDemoData() { state.findings=JSON.parse(localStorage.getItem('asteria-findings') || 'null') || []; state.auditTests=JSON.parse(localStorage.getItem('asteria-audit-tests') || 'null') || []; if(!state.auditTests.length) state.auditTests=['A.5.1','A.5.9','A.5.15','A.6.3','A.8.8','A.8.13'].map((ref,index)=>({id:`AT-${index+1}`,auditId:1,controlRef:ref,procedure:`Review the control intent, current implementation, owner evidence, and latest review record.`,result:index<2?'Pass':index===2?'Partial':'Not tested',evidenceIds:controls.find(c=>c.ref===ref)?.status==='implemented'?state.evidence.filter(e=>e.refs.includes(ref)).map(e=>e.id):[],notes:'',findingId:null})); syncImportedGaps(); save(); }
function syncImportedGaps() { if(!state.crfControls.length) return; const existing=new Map(state.gaps.map(g=>[g.id,g])); state.crfControls.filter(c=>c.gap || c.action || c.findings).forEach(c=>{ if(!existing.has(c.id)) existing.set(c.id,{id:c.id,family:c.family,description:c.description,gap:c.gap || c.findings || 'Assessment observation requires review.',risk:c.risk || 'Medium',action:c.action || 'Define and assign a corrective action.',owner:'Unassigned',due:'',status:'Open',source:'CST CRF'}); }); state.gaps=Array.from(existing.values()); }
async function loadCRFControls() { if(!state.crfControls.length && typeof XLSX !== 'undefined') { try { const response=await fetch('fictional-crf-catalogue.json'); const workbook=XLSX.read(await response.arrayBuffer(),{type:'array'}); const rows=XLSX.utils.sheet_to_json(workbook.Sheets['CRF CST 2026'],{header:1,defval:''}); state.crfControls=rows.slice(6).filter(row=>row[1] && row[3]).map(row=>({id:String(row[1]),family:String(row[2]),description:String(row[3]),evidence:String(row[6] || ''),findings:String(row[7] || ''),gap:String(row[8] || ''),risk:String(row[9] || ''),action:String(row[10] || ''),status:String(row[11] || 'Not assessed')})); localStorage.setItem('asteria-crf-controls',JSON.stringify(state.crfControls)); syncImportedGaps(); save(); if(state.page==='controls' || state.assignmentSet==='crf') render(); } catch(error) { console.warn('CRF workbook could not be loaded',error); } } }
function findingBadge(status) { return `<span class="badge ${status==='Closed'?'green':status==='In progress'?'amber':'red'}">${status}</span>`; }
function resultBadge(result) { return `<span class="badge ${result==='Pass'?'green':result==='Partial'?'amber':result==='Fail'?'red':'gray'}">${result}</span>`; }
function auditProgress(audit) { const tests=state.auditTests.filter(t=>t.auditId===audit.id); return tests.length ? Math.round(tests.filter(t=>t.result!=='Not tested').length/tests.length*100) : 0; }
function openAuditCreate() { document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Assurance / New audit</div><h2 style="margin-top:7px">Create internal audit</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="field"><label>Audit name</label><input id="audit-name" value="ISO 27001 readiness audit" /></div><div class="field"><label>Scope</label><textarea id="audit-scope" placeholder="Define the framework, business units, and processes covered.">ISO 27001 Annex A controls and evidence traceability</textarea></div><div class="detail-grid"><div class="field"><label>Audit lead</label><input id="audit-lead" value="Security Office" /></div><div class="field"><label>Planned date</label><input id="audit-date" type="date" value="2026-09-15" /></div></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveAuditCreate()">Create audit</button></div></div></div></div>`); }
function saveAuditCreate() { const audit={id:Date.now(),name:document.getElementById('audit-name').value.trim() || 'Internal audit',scope:document.getElementById('audit-scope').value.trim(),lead:document.getElementById('audit-lead').value.trim(),date:document.getElementById('audit-date').value,status:'Planned',progress:0}; state.audits.push(audit); controls.slice(0,6).forEach((c,index)=>state.auditTests.push({id:`AT-${audit.id}-${index}`,auditId:audit.id,controlRef:c.ref,procedure:`Review ${c.title}, implementation records, and current supporting evidence.`,result:'Not tested',evidenceIds:[],notes:'',findingId:null})); save(); closeModal(); render(); toast('Internal audit created with a control test program'); }
function openAuditTest(id) { const test=state.auditTests.find(item=>item.id===id); const c=controls.find(item=>item.ref===test.controlRef); if(!test || !c) return; document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${test.controlRef} / Control test</div><h2 style="margin-top:7px">${c.title}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="source-description"><label>Test procedure</label><p>${test.procedure}</p></div><div class="field"><label>Test result</label><select id="audit-result"><option ${test.result==='Not tested'?'selected':''}>Not tested</option><option ${test.result==='Pass'?'selected':''}>Pass</option><option ${test.result==='Partial'?'selected':''}>Partial</option><option ${test.result==='Fail'?'selected':''}>Fail</option></select></div><div class="field"><label>Evidence sampled</label><select id="audit-evidence" class="select evidence-modal-select" multiple size="4">${evidenceOptions(test.controlRef)}</select></div><div class="field"><label>Auditor notes</label><textarea id="audit-notes" placeholder="Record sample details, interviews, observations, and exceptions.">${test.notes || ''}</textarea></div><div class="field"><label>Finding severity if partial/fail</label><select id="audit-severity"><option>Low</option><option>Medium</option><option>High</option></select></div><div class="field"><label>Finding / observation</label><textarea id="audit-finding" placeholder="Describe the issue that should become a corrective action."></textarea></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveAuditTest('${id}')">Save test result</button></div></div></div></div>`); }
function saveAuditTest(id) { const test=state.auditTests.find(item=>item.id===id); const result=document.getElementById('audit-result').value; test.result=result; test.notes=document.getElementById('audit-notes').value.trim(); test.evidenceIds=Array.from(document.getElementById('audit-evidence').selectedOptions).map(option=>Number(option.value)); const findingText=document.getElementById('audit-finding').value.trim(); if((result==='Partial' || result==='Fail') && findingText) { const existing=state.findings.find(f=>f.id===test.findingId); if(existing) { existing.description=findingText; existing.severity=document.getElementById('audit-severity').value; } else { const finding={id:`F-${Date.now()}`,source:'Internal audit',controlRef:test.controlRef,title:controls.find(c=>c.ref===test.controlRef)?.title || test.controlRef,description:findingText,severity:document.getElementById('audit-severity').value,status:'Open',owner:'Unassigned',due:'',action:'Define corrective action and attach closure evidence.',evidenceIds:[]}; state.findings.push(finding); test.findingId=finding.id; } } save(); closeModal(); render(); toast(`${test.controlRef} audit test saved as ${result}`); }
function openFinding(id) { const finding=state.findings.find(item=>item.id===id); if(!finding) return; document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><div class="eyebrow">${finding.id} / Finding</div><h2 style="margin-top:7px">${finding.title}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modal-body"><div class="gap-summary"><label>Source</label><p>${finding.source} · ${finding.controlRef}</p><label>Finding</label><p>${finding.description}</p></div><div class="detail-grid"><div class="field"><label>Severity</label><select id="finding-severity"><option ${finding.severity==='Low'?'selected':''}>Low</option><option ${finding.severity==='Medium'?'selected':''}>Medium</option><option ${finding.severity==='High'?'selected':''}>High</option></select></div><div class="field"><label>Status</label><select id="finding-status"><option ${finding.status==='Open'?'selected':''}>Open</option><option ${finding.status==='In progress'?'selected':''}>In progress</option><option ${finding.status==='Closed'?'selected':''}>Closed</option></select></div></div><div class="field"><label>Corrective action</label><textarea id="finding-action">${finding.action}</textarea></div><div class="detail-grid"><div class="field"><label>Owner</label><input id="finding-owner" value="${finding.owner}" /></div><div class="field"><label>Due date</label><input id="finding-due" value="${finding.due}" /></div></div><div class="field"><label>Closure evidence</label><select id="finding-evidence" class="select evidence-modal-select" multiple size="3">${evidenceOptions(finding.id)}</select></div><div class="modal-actions"><button class="button button-quiet" onclick="closeModal()">Cancel</button><button class="button button-primary" onclick="saveFinding('${id}')">Save finding</button></div></div></div></div>`); }
function saveFinding(id) { const f=state.findings.find(item=>item.id===id); f.severity=document.getElementById('finding-severity').value; f.status=document.getElementById('finding-status').value; f.action=document.getElementById('finding-action').value.trim(); f.owner=document.getElementById('finding-owner').value.trim(); f.due=document.getElementById('finding-due').value.trim(); f.evidenceIds=Array.from(document.getElementById('finding-evidence').selectedOptions).map(option=>Number(option.value)); save(); closeModal(); render(); toast(`${id} updated`); }
function auditFindingsPanel() { const findings=state.findings || []; return `<div class="card panel"><div class="panel-head"><div><h2>Findings and corrective actions</h2><p>${findings.filter(f=>f.status!=='Closed').length} open findings · each needs an owner and closure proof</p></div><button class="link" onclick="navigate('actions')">Open action plan →</button></div>${findings.length ? `<div class="finding-list">${findings.map(f=>`<div class="finding-row"><span class="control-ref">${f.id}</span><div><strong>${f.title}</strong><p>${f.description}</p><small>${f.controlRef} · ${f.owner} · due ${f.due || 'not set'}</small></div><div>${findingBadge(f.status)}<br>${riskBadge(f.severity)}</div><button class="table-action" onclick="openFinding('${f.id}')">Review</button></div>`).join('')}</div>` : '<div class="empty-state">No audit findings yet. Test a control and record a partial or failed result.</div>'}</div>`; }
function auditsPage() { const audit=state.audits[0]; const tests=state.auditTests.filter(t=>t.auditId===audit.id); const progress=auditProgress(audit); const rows=tests.map(test=>{const c=controls.find(item=>item.ref===test.controlRef); return `<tr><td><span class="control-ref">${test.controlRef}</span></td><td><div class="control-title">${c?.title || test.controlRef}</div><div class="control-sub">${test.procedure}</div></td><td>${resultBadge(test.result)}</td><td>${test.evidenceIds.length} sampled</td><td><button class="table-action" onclick="openAuditTest('${test.id}')">Test control →</button></td></tr>`;}).join(''); return layout(`<div class="page-head"><div><div class="eyebrow">Assurance / Internal audit program</div><h1>Internal audits</h1><p class="subhead">Run a repeatable control test, record the result, raise a finding, and move corrective work into closure.</p></div><button class="button button-primary" onclick="openAuditCreate()">+ New audit</button></div><div class="stats"><div class="card stat-card"><div class="eyebrow">Audit progress</div><div class="stat-number">${progress}%</div><div class="stat-meta">${tests.filter(t=>t.result!=='Not tested').length} of ${tests.length} tests completed</div></div><div class="card stat-card"><div class="eyebrow">Tests passed</div><div class="stat-number">${tests.filter(t=>t.result==='Pass').length}</div><div class="stat-meta good">Evidence-backed results</div></div><div class="card stat-card"><div class="eyebrow">Findings</div><div class="stat-number">${state.findings.length}</div><div class="stat-meta">Open and closed</div></div><div class="card stat-card"><div class="eyebrow">Audit status</div><div class="stat-number" style="font-size:22px">${audit.status}</div><div class="stat-meta">Lead: ${audit.lead}</div></div></div><div class="card panel" data-tour="audit-workspace"><div class="panel-head"><div><h2>${audit.name}</h2><p>${audit.scope} · ${audit.date}</p></div><span class="badge ${audit.status==='In progress'?'amber':'gray'}">${audit.status}</span></div><div class="progress-line"><i style="width:${progress}%"></i></div><div style="overflow:auto"><table><thead><tr><th>Control</th><th>Test procedure</th><th>Result</th><th>Evidence</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>${auditFindingsPanel()}`, 'Internal audits'); }
function actionsPage() { const active=state.gaps.filter(g=>g.status!=='Closed'); const findings=state.findings.filter(f=>f.status!=='Closed'); return layout(`<div class="page-head"><div><div class="eyebrow">Remediation / Corrective action plan</div><h1>Action plan</h1><p class="subhead">One accountable list for assessment gaps and internal-audit findings. Close work only when closure evidence is attached.</p></div><button class="button button-primary" onclick="navigate('gaps')">Review gap register →</button></div><div class="stats"><div class="card stat-card"><div class="eyebrow">Active actions</div><div class="stat-number">${active.length}</div><div class="stat-meta">Assessment remediation</div></div><div class="card stat-card"><div class="eyebrow">Audit findings</div><div class="stat-number">${findings.length}</div><div class="stat-meta">Need corrective work</div></div><div class="card stat-card"><div class="eyebrow">High risk</div><div class="stat-number">${active.filter(g=>g.risk==='High').length + findings.filter(f=>f.severity==='High').length}</div><div class="stat-meta">Management attention</div></div></div><div class="card panel"><div class="panel-head"><div><h2>Assessment actions</h2><p>${active.length} active gaps from the imported report</p></div><button class="link" onclick="exportActionsExcel()">Export plan to Excel</button></div><div style="overflow:auto"><table><thead><tr><th>Gap</th><th>Action</th><th>Owner</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${active.map(g=>`<tr><td><span class="control-ref">${g.id}</span><div class="control-sub">${g.family}<br>${riskBadge(g.risk)}</div></td><td><div class="control-title">${g.action}</div><div class="control-sub">${g.gap}</div></td><td>${g.owner}</td><td>${g.due || 'Not set'}</td><td><select class="select action-status" onchange="updateGapStatus('${g.id}',this.value)"><option ${g.status==='Open'?'selected':''}>Open</option><option ${g.status==='In progress'?'selected':''}>In progress</option><option>Closed</option></select></td><td><button class="table-action" onclick="openGap('${g.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div></div><div class="card panel"><div class="panel-head"><div><h2>Internal-audit findings</h2><p>Findings become corrective actions without re-entering the control context.</p></div></div>${findings.length ? `<div class="finding-list">${findings.map(f=>`<div class="finding-row"><span class="control-ref">${f.id}</span><div><strong>${f.title}</strong><p>${f.action}</p><small>${f.controlRef} · ${f.owner} · due ${f.due || 'not set'}</small></div><div>${findingBadge(f.status)}<br>${riskBadge(f.severity)}</div><button class="table-action" onclick="openFinding('${f.id}')">Edit</button></div>`).join('')}</div>` : '<div class="empty-state">No open audit findings.</div>'}</div>`, 'Action plan'); }
function updateGapStatus(id,status) { const gap=state.gaps.find(item=>item.id===id); if(status==='Closed' && !state.evidence.some(e=>e.refs.includes(id))) return toast('Attach closure evidence before closing this gap'); gap.status=status; save(); render(); toast(`Gap ${id} marked ${status.toLowerCase()}`); }
function resetDemoData() { ['asteria-evidence','asteria-evidence-details','asteria-documents','asteria-gaps','asteria-audits','asteria-findings','asteria-audit-tests','asteria-statuses','asteria-soa'].forEach(key=>localStorage.removeItem(key)); sessionStorage.removeItem('asteria-tour-complete'); window.location.reload(); }
function render() { const pages={dashboard:dashboard,controls:controlsPage,soa:soaPage,evidence:evidencePage,policies:()=>documentsPage('policy'),procedures:()=>documentsPage('procedure'),'document-update':documentUpdatePage,'evidence-update':evidenceUpdatePage,gaps:gapsPage,audits:auditsPage,actions:actionsPage,roadmap:roadmapPage}; document.getElementById('tour-layer')?.remove(); if(!state.authenticated) { document.getElementById('app').innerHTML=loginPage(); return; } document.getElementById('app').innerHTML=pages[state.page](); decorateLifecycleButtons(); const tourTarget={policies:'.card.panel',procedures:'.card.panel',gaps:'.card.panel',audits:'.card.panel'}[state.page]; const tourName={policies:'document-register',procedures:'document-register',gaps:'gap-register',audits:'audit-workspace'}[state.page]; if(tourTarget && tourName) document.querySelector(tourTarget)?.setAttribute('data-tour',tourName); if(!state.tourComplete) requestAnimationFrame(()=>{renderTour();addTourSkip();}); }
ensureDemoData();
render();
function purgeSensitiveDemoState() { const version='fictional-demo-v1'; if(localStorage.getItem('asteria-demo-data-version')===version) return; ['asteria-evidence','asteria-evidence-details','asteria-documents','asteria-gaps','asteria-audits','asteria-findings','asteria-audit-tests','asteria-crf-controls','asteria-crf-soa','asteria-assets','asteria-statuses','asteria-soa'].forEach(key=>localStorage.removeItem(key)); state.evidence=seedEvidence; state.evidenceDetails={}; state.documents=seedDocuments; state.gaps=seedGaps; state.audits=seedAudits; state.findings=[]; state.auditTests=[]; state.crfControls=dummyCRFControls(); state.assets=dummyAssets(); state.crfSoa={}; state.soaSet='iso'; localStorage.setItem('asteria-demo-data-version',version); save(); assetSave(); }
function loadCRFControls() { if(!state.crfControls?.length) state.crfControls=dummyCRFControls(); syncImportedGaps(); save(); if(state.page==='controls' || state.soaSet==='crf') render(); }
function layout(content,title) { return `<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#"><span class="brand-mark"></span><span class="brand-name">asteria</span></a><div class="eyebrow">Information security</div><nav class="nav"><div class="nav-section-label">Command center</div>${nav('dashboard','◒','Overview')}${nav('assets','◆','Asset management')}${nav('roadmap','＋','Product direction')}<div class="nav-section-label">ISMS</div>${nav('controls','⊙','Control catalogue')}${nav('soa','▤','Statement of Applicability')}${nav('policies','▤','Policies')}${nav('procedures','≡','Procedures')}${nav('evidence','□','Evidence library')}<div class="nav-section-label">Assurance</div>${nav('audits','◌','Internal audits')}${nav('gaps','△','Gap assessment')}${nav('actions','↗','Action plan')}</nav><div class="sidebar-footer"><div class="org-chip"><span class="avatar">AT</span><div><strong>Atlas Demo Co.</strong><small>Fictional workspace · Demo</small></div></div></div></aside><main class="main"><header class="topbar"><div><button class="mobile-menu" onclick="toggleMenu()">☰</button><span class="crumb">Workspace / <strong>${title}</strong></span></div><div class="top-actions"><div class="workspace-context"><span class="avatar">AT</span><div><strong>Atlas Demo Co.</strong><small>Fictional workspace</small></div></div><button class="icon-btn" title="Notifications" onclick="toast('Notifications are clear')">♧</button><div class="user-pill"><span class="avatar">DO</span><span>Demo Operator</span><button class="logout" onclick="logout()">Sign out</button></div></div></header><section class="content">${content}</section></main></div>`; }
function dashboard() {
  const sc = score();
  const impl = Object.values(state.statuses).filter(s=>s==='implemented').length;
  const partial = Object.values(state.statuses).filter(s=>s==='partial').length;
  const open = Object.values(state.statuses).filter(s=>s==='open').length;
  const na = Object.values(state.statuses).filter(s=>s==='na').length;
  const fresh = state.evidence.filter(e=>e.freshness==='fresh').length;
  const expiring = state.evidence.filter(e=>e.freshness==='expiring').length;
  const expired = state.evidence.filter(e=>e.freshness==='expired').length;
  const risks = state.risks || [];
  const rscore = r => Math.max(1, Math.min(25, (Number(r.likelihood) || 1) * (Number(r.impact) || 1)));
  const rlevel = n => n >= 16 ? 'Critical' : n >= 10 ? 'High' : n >= 5 ? 'Medium' : 'Low';
  const exposed = risks.filter(r => ['High','Critical'].includes(rlevel(rscore(r))));
  const treatment = risks.filter(r => r.status === 'Open' || r.status === 'In progress').length;
  const gapOpen = state.gaps.filter(g => g.status === 'Open' || g.status === 'In progress').length;
  const auditLive = state.audits.filter(a => a.status === 'In progress').length;
  const themeRows = [['A5',37],['A6',8],['A7',14],['A8',34]].map(([theme,total]) => { const list=controls.filter(c=>c.theme===theme); const done=Math.round(list.reduce((n,c)=>n+(state.statuses[c.ref]==='implemented'?1:state.statuses[c.ref]==='partial'?.5:0),0)/list.length*100); return `<div class="theme-row"><div class="theme-name">${themes[theme]}<span>${total} controls</span></div><div class="bar"><i style="width:${done}%"></i></div><div class="percent">${done}%</div></div>` }).join('');
  const dist = status => Math.round(status / 93 * 100);
  const topRisks = [...risks].sort((a,b) => rscore(b) - rscore(a)).slice(0, 4);
  const riskRows = topRisks.map(r => { const n = rscore(r); const lv = rlevel(n); return `<button class="risk-mini" onclick="openRisk('${r.id}')"><span class="risk-pill ${lv.toLowerCase()}">${lv}</span><span class="risk-mini-title">${r.title}<small>${r.owner || 'Unassigned'} · treatment due ${r.due || 'not set'}</small></span><b>${n}/25</b></button>`; }).join('');
  const attention = [`<div class="activity-item"><span class="activity-dot"></span><p><strong>${open} controls</strong> still need an owner and implementation plan.</p><span class="activity-time">NOW</span></div>`, `<div class="activity-item"><span class="activity-dot" style="background:var(--gold);box-shadow:0 0 0 5px #fbf1dc"></span><p><strong>${expiring + expired} evidence items</strong> are expiring or no longer current.</p><span class="activity-time">REVIEW</span></div>`, `<div class="activity-item"><span class="activity-dot" style="background:var(--coral);box-shadow:0 0 0 5px #fdebe6"></span><p><strong>${Object.values(state.soa).filter(x=>!x.applicable && !x.justification).length} SoA decisions</strong> need a written rationale.</p><span class="activity-time">OPEN</span></div>`].concat(exposed.length ? [`<div class="activity-item"><span class="activity-dot" style="background:#9e3e35;box-shadow:0 0 0 5px #f6dedb"></span><p><strong>${exposed.length} high or critical risks</strong> need a treatment decision.</p><span class="activity-time">RISK</span></div>`] : []).concat(auditLive ? [`<div class="activity-item"><span class="activity-dot" style="background:#6b87a6;box-shadow:0 0 0 5px #e3eaf2"></span><p><strong>${auditLive} internal audit</strong> is in progress with open findings.</p><span class="activity-time">AUDIT</span></div>`] : []).join('');
  return layout(`<div class="page-head"><div><div class="eyebrow">Atlas Demo Co. / ISMS readiness</div><h1>Certification, in view.</h1><p class="subhead">Every ISO 27001 control, its applicability decision, the evidence that proves it — and the risks that still need your attention.</p></div><button class="button button-primary" onclick="navigate('controls')">Review controls &nbsp;→</button></div><div class="stats"><div class="card score-card" data-tour="overview-score"><div><div class="eyebrow">Certification readiness</div><div class="score-value">${sc}<span>/100</span></div><div class="stat-meta" style="color:#a4b4b5">Evidence coverage included</div></div><div class="ring"><b>${sc}%</b></div></div><div class="card stat-card" onclick="navigate('risk')" title="Open risk register"><div class="eyebrow">Risk exposure</div><div class="stat-number">${exposed.length}</div><div class="stat-meta ${exposed.length ? 'bad' : 'good'}">${exposed.length ? 'High or critical risks' : 'No high exposure'} · ${treatment} in treatment</div></div><div class="card stat-card" onclick="navigate('gaps')" title="Open gap assessment"><div class="eyebrow">Open actions</div><div class="stat-number">${gapOpen}</div><div class="stat-meta">Gap remediation items</div></div><div class="card stat-card" onclick="navigate('evidence')" title="Open evidence library"><div class="eyebrow">Evidence watch</div><div class="stat-number">${expiring + expired}</div><div class="stat-meta ${expiring + expired ? 'bad' : 'good'}">${fresh} current · ${expiring} expiring</div></div></div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h2>Implementation status</h2><p>All 93 Annex A controls, by current status</p></div><button class="link" onclick="navigate('controls')">Control catalogue →</button></div><div class="dist-bar"><i style="width:${dist(impl)}%;background:#79a58d"></i><i style="width:${dist(partial)}%;background:#c79b58"></i><i style="width:${dist(open)}%;background:#c9684d"></i><i style="width:${dist(na)}%;background:#d9dcd3"></i></div><div class="dist-legend"><span><i style="background:#79a58d"></i>Implemented <b>${impl}</b></span><span><i style="background:#c79b58"></i>Partial <b>${partial}</b></span><span><i style="background:#c9684d"></i>Not started <b>${open}</b></span><span><i style="background:#d9dcd3"></i>Not applicable <b>${na}</b></span></div></div><div class="card panel"><div class="panel-head"><div><h2>Annex A progress</h2><p>Implementation by control theme</p></div><button class="link" onclick="navigate('controls')">View all 93 →</button></div>${themeRows}</div></div><div class="grid-2"><div class="card panel"><div class="panel-head"><div><h2>Risk register</h2><p>Highest exposure first, linked to the risk management module</p></div><button class="link" onclick="navigate('risk')">Open risk register →</button></div>${risks.length ? riskRows : '<div class="empty-state">No risks yet. Open Risk Management to start the register.</div>'}</div><div class="card panel"><div class="panel-head"><div><h2>What needs attention</h2><p>Small actions that move readiness forward</p></div></div><div class="activity">${attention}</div></div></div><div class="callout"><div><h3>Keep your audit trail one step ahead.</h3><p>Complete your applicability decisions before collecting more evidence.</p></div><button class="button button-light" onclick="navigate('soa')">Open SoA builder →</button></div>`, 'Overview');
}
purgeSensitiveDemoState();
render();
