function render() { const pages={dashboard:dashboard,assets:assetPage,controls:controlsPage,soa:soaPage,evidence:evidencePage,policies:()=>documentsPage('policy'),procedures:()=>documentsPage('procedure'),'document-update':documentUpdatePage,'evidence-update':evidenceUpdatePage,gaps:gapsPage,audits:auditsPage,actions:actionsPage,roadmap:roadmapPage}; document.getElementById('tour-layer')?.remove(); if(!state.authenticated) { document.getElementById('app').innerHTML=loginPage(); return; } document.getElementById('app').innerHTML=pages[state.page](); decorateLifecycleButtons(); const tourTarget={policies:'.card.panel',procedures:'.card.panel',gaps:'.card.panel',audits:'.card.panel'}[state.page]; const tourName={policies:'document-register',procedures:'document-register',gaps:'gap-register',audits:'audit-workspace'}[state.page]; if(tourTarget && tourName) document.querySelector(tourTarget)?.setAttribute('data-tour',tourName); if(!state.tourComplete) requestAnimationFrame(()=>{renderTour();addTourSkip();}); }
